-- ============================================
-- LUMA — Thème 10 (Enquête) : 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"witness": "le témoin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "witness", "text": "I already told the other officer everything I know!", "text_fr": "J''ai déjà tout dit à l''autre officier !", "choices": [{"text": "I understand, but I''d appreciate hearing it directly from you.", "text_fr": "Je comprends, mais j''apprécierais l''entendre directement de vous.", "next": "n2"}, {"text": "This won''t take long. Can you walk me through what you saw?", "text_fr": "Ça ne prendra pas longtemps. Vous pouvez me raconter ce que vous avez vu ?", "next": "n2b"}]}, "n2": {"speaker": "witness", "text": "(Sighs) Fine. I was walking my dog when I heard glass breaking upstairs.", "text_fr": "(Soupire) Bon. Je promenais mon chien quand j''ai entendu du verre se briser à l''étage.", "choices": [{"text": "What time was this, approximately?", "text_fr": "À quelle heure environ ?", "next": "n3"}]}, "n2b": {"speaker": "witness", "text": "Alright. It was around 9pm, I was walking my dog past the building.", "text_fr": "D''accord. C''était vers 21h, je promenais mon chien devant le bâtiment.", "choices": [{"text": "What happened next?", "text_fr": "Qu''est-ce qui s''est passé ensuite ?", "next": "n3"}]}, "n3": {"speaker": "witness", "text": "Right around 9pm. Then I saw a figure run out the back exit.", "text_fr": "Vers 21h justement. Puis j''ai vu une silhouette sortir en courant par la sortie arrière.", "choices": [{"text": "Can you describe this person at all?", "text_fr": "Vous pouvez décrire cette personne un minimum ?", "next": "n4"}, {"text": "Did they seem to notice you were there?", "text_fr": "Elle a semblé remarquer votre présence ?", "next": "n4b"}]}, "n4": {"speaker": "witness", "text": "Tall, wearing a dark hoodie. I didn''t see their face clearly, it was too dark.", "text_fr": "Grand, portant un sweat à capuche sombre. J''ai pas bien vu son visage, il faisait trop sombre.", "choices": [{"text": "That''s still helpful. Anything else stand out?", "text_fr": "C''est quand même utile. Autre chose qui vous a marqué ?", "next": "n5"}]}, "n4b": {"speaker": "witness", "text": "No, I don''t think so — they seemed focused on getting away quickly.", "text_fr": "Non, je pense pas — ils semblaient concentrés sur le fait de partir vite.", "choices": [{"text": "Did you notice which direction they went?", "text_fr": "Vous avez remarqué dans quelle direction ils sont partis ?", "next": "n5"}]}, "n5": {"speaker": "witness", "text": "They ran toward the alley on Fifth Street, if that helps.", "text_fr": "Ils ont couru vers la ruelle sur la Cinquième Rue, si ça aide.", "choices": [{"text": "That''s very helpful, thank you for your time.", "text_fr": "C''est très utile, merci pour votre temps.", "next": "end_gathered"}]}, "end_gathered": {"speaker": "witness", "text": "I hope you catch them. That building''s been broken into twice this year already.", "text_fr": "J''espère que vous les attraperez. Ce bâtiment a déjà été cambriolé deux fois cette année.", "end": true, "ending_label": "Premier témoignage recueilli 🕵️📝"}}}'::jsonb, is_playable = true
where title = 'Interroger un premier témoin'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"partner": "votre collègue"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "Alright, we''ve got the scene secured. What catches your eye first?", "text_fr": "Bon, on a sécurisé la scène. Qu''est-ce qui attire votre œil en premier ?", "choices": [{"text": "That broken window looks like the point of entry.", "text_fr": "Cette fenêtre cassée ressemble au point d''entrée.", "next": "n2"}, {"text": "There''s a muddy footprint by the door — worth examining.", "text_fr": "Il y a une empreinte de pas boueuse près de la porte — vaut le coup d''être examinée.", "next": "n2b"}]}, "n2": {"speaker": "partner", "text": "Good eye. Glass fragments are scattered inward, suggesting forced entry from outside.", "text_fr": "Bon œil. Les fragments de verre sont dispersés vers l''intérieur, suggérant une entrée forcée depuis l''extérieur.", "choices": [{"text": "Let''s dust for prints around the window frame.", "text_fr": "Cherchons des empreintes autour du cadre de la fenêtre.", "next": "n3"}]}, "n2b": {"speaker": "partner", "text": "Interesting — that print looks fresh, and it doesn''t match either resident''s shoes.", "text_fr": "Intéressant — cette empreinte semble fraîche, et elle ne correspond à aucune chaussure des résidents.", "choices": [{"text": "Let''s photograph it and get a cast made.", "text_fr": "Photographions-la et faisons un moulage.", "next": "n3"}]}, "n3": {"speaker": "partner", "text": "Good call. What else do you want to check before we move on?", "text_fr": "Bonne idée. Quoi d''autre voulez-vous vérifier avant qu''on avance ?", "choices": [{"text": "Let''s check if anything valuable is missing from this room.", "text_fr": "Vérifions si quelque chose de précieux manque dans cette pièce.", "next": "n4"}, {"text": "I want to see if there are security cameras nearby.", "text_fr": "Je veux voir s''il y a des caméras de sécurité à proximité.", "next": "n4"}]}, "n4": {"speaker": "partner", "text": "Good thinking. Let''s follow up on both leads back at the station.", "text_fr": "Bonne pensée. Suivons les deux pistes de retour au poste.", "choices": [{"text": "Agreed, this scene has given us a solid starting point.", "text_fr": "D''accord, cette scène nous a donné un bon point de départ.", "next": "end_clue"}]}, "end_clue": {"speaker": "partner", "text": "Nice work. This is exactly the kind of detail that cracks a case.", "text_fr": "Beau travail. C''est exactement le genre de détail qui résout une affaire.", "end": true, "ending_label": "Indice clé repéré sur la scène 🔍✅"}}}'::jsonb, is_playable = true
where title = 'Repérer un indice sur une scène de crime'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
